  vi.useFakeTimers();
  const cb = vi.fn();
  const { result } = renderHook(() => useLongPress(cb, 500));
  act(() => result.current.onMouseDown());
  vi.advanceTimersByTime(500);
  expect(cb).toHaveBeenCalledTimes(1);
  vi.useRealTimers();
});

